export const envelope = [15, 18, 16];

export default function build(api) {
  const { set, heightAt, theme } = api;

  // 1. Resolve Theme Palette with reliable fallbacks
  const woodPlanks = theme.wood?.planks || "minecraft:spruce_planks";
  const woodLog = theme.wood?.log || "minecraft:dark_oak_log";
  const woodStripped = theme.wood?.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = theme.wood?.stairs || "minecraft:spruce_stairs";
  const woodSlab = theme.wood?.slab || "minecraft:spruce_slab";
  const woodFence = theme.wood?.fence || "minecraft:spruce_fence";
  const woodTrapdoor = theme.wood?.trapdoor || "minecraft:spruce_trapdoor";
  const woodDoor = theme.wood?.door || "minecraft:spruce_door";

  const stonePlinth = theme.ground?.plinth || theme.stone?.primary || "minecraft:stone_bricks";
  const stonePrimary = theme.stone?.primary || "minecraft:cobblestone";
  const stoneWall = theme.stone?.wall || "minecraft:cobblestone_wall";
  const stoneSlab = theme.stone?.slab || "minecraft:cobblestone_slab";

  const roofStairs = theme.roof?.stairs || woodStairs;
  const roofSlab = theme.roof?.slab || woodSlab;
  const roofSolid = theme.roof?.solid || woodPlanks;

  // Utility helpers
  function safeSet(x, y, z, block) {
    if (x >= 0 && x < envelope[0] && y >= 0 && y < envelope[1] && z >= 0 && z < envelope[2]) {
      set(x, y, z, block);
    }
  }

  // Rule 6: Ground conformity helper — builds foundation down to real terrain
  function groundPillar(x, z, topY, material) {
    const h = heightAt(x, z);
    const minY = Math.min(h, topY);
    const maxY = Math.max(h, topY);
    for (let y = minY; y <= maxY; y++) {
      safeSet(x, y, z, material);
    }
  }

  // ==========================================
  // 2. FOUNDATIONS & BOARDWALK PLATFORM
  // ==========================================

  // Depot Office Foundation (X: 1..7, Z: 6..14)
  for (let x = 1; x <= 7; x++) {
    for (let z = 6; z <= 14; z++) {
      const isPerimeter = (x === 1 || x === 7 || z === 6 || z === 14);
      groundPillar(x, z, 0, isPerimeter ? stonePlinth : stonePrimary);
      // Floor plane at Y=0
      safeSet(x, 0, z, woodPlanks);
    }
  }

  // Boardwalk Platform (X: 0..14, Z: 1..5) and Tower Walkway (X: 9..13, Z: 5..8)
  for (let x = 0; x <= 14; x++) {
    for (let z = 1; z <= 5; z++) {
      // Platform pilings under structural grid
      if (x % 3 === 0 || x === 14 || z === 1 || z === 5) {
        groundPillar(x, z, 0, stonePlinth);
      } else {
        groundPillar(x, z, 0, stonePrimary);
      }
      // Wooden boardwalk walking deck at Y=1
      safeSet(x, 1, z, woodPlanks);
    }
  }

  // Connector walkway between boardwalk and water tower base
  for (let x = 9; x <= 13; x++) {
    for (let z = 6; z <= 7; z++) {
      groundPillar(x, z, 0, stonePlinth);
      safeSet(x, 1, z, woodPlanks);
    }
  }

  // Boardwalk front steps down to ground (Z=0, X: 1..13)
  for (let x = 1; x <= 13; x++) {
    groundPillar(x, 0, 0, stonePlinth);
    safeSet(x, 0, 0, `${woodStairs}[facing=south,half=bottom]`);
  }

  // Railway track terminus ballast & ties (X: 14, Z: 0..5)
  for (let z = 0; z <= 5; z++) {
    groundPillar(14, z, 0, stonePrimary);
    safeSet(14, 1, z, `${woodSlab}[type=bottom]`);
  }
  // Track buffer bumper at end of rail spur
  safeSet(14, 1, 5, `${woodLog}[axis=z]`);
  safeSet(14, 2, 5, `${woodStairs}[facing=north,half=bottom]`);
  safeSet(14, 2, 4, "minecraft:iron_bars");

  // ==========================================
  // 3. DEPOT BUILDING (X: 1..7, Z: 6..14)
  // ==========================================

  // Vertical timber log posts at corners and bays
  const depotPosts = [
    [1, 6], [7, 6], [1, 14], [7, 14],
    [1, 10], [7, 10], [4, 14]
  ];
  for (const [px, pz] of depotPosts) {
    for (let y = 1; y <= 5; y++) {
      safeSet(px, y, pz, `${woodLog}[axis=y]`);
    }
  }

  // North wall (Z=6) - Front facade with ticket office door & windows
  for (let x = 2; x <= 6; x++) {
    for (let y = 1; y <= 4; y++) {
      if (x === 4) {
        // Doorway
        if (y === 1) safeSet(x, y, 6, `${woodDoor}[facing=north,half=lower]`);
        else if (y === 2) safeSet(x, y, 6, `${woodDoor}[facing=north,half=upper]`);
        else safeSet(x, y, 6, woodPlanks);
      } else if (x === 2 || x === 6) {
        // Ticket / waiting room windows
        if (y === 2 || y === 3) safeSet(x, y, 6, woodFence);
        else safeSet(x, y, 6, woodPlanks);
      } else {
        safeSet(x, y, 6, woodPlanks);
      }
    }
  }

  // South wall (Z=14)
  for (let x = 2; x <= 6; x++) {
    if (x === 4) continue; // Skip post
    for (let y = 1; y <= 4; y++) {
      if ((x === 3 || x === 5) && (y === 2 || y === 3)) {
        safeSet(x, y, 14, woodFence);
      } else {
        safeSet(x, y, 14, woodPlanks);
      }
    }
  }

  // West wall (X=1) and East wall (X=7)
  for (let z = 7; z <= 13; z++) {
    if (z === 10) continue; // Skip post
    for (let y = 1; y <= 4; y++) {
      // West wall
      if ((z === 8 || z === 12) && y === 2) {
        safeSet(1, y, z, woodFence);
      } else {
        safeSet(1, y, z, woodPlanks);
      }

      // East wall
      if ((z === 8 || z === 12) && y === 2) {
        safeSet(7, y, z, woodFence);
      } else {
        safeSet(7, y, z, woodPlanks);
      }
    }
  }

  // Ceiling over depot room at Y=5
  for (let x = 2; x <= 6; x++) {
    for (let z = 7; z <= 13; z++) {
      safeSet(x, 5, z, woodPlanks);
    }
  }

  // Gabled Roof over depot (Y=5..8, X: 0..8, Z: 5..15)
  for (let z = 5; z <= 15; z++) {
    // Eaves course (Y=5)
    safeSet(0, 5, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(0, 4, z, `${roofStairs}[facing=west,half=top]`);
    safeSet(8, 5, z, `${roofStairs}[facing=west,half=bottom]`);
    safeSet(8, 4, z, `${roofStairs}[facing=east,half=top]`);

    // Slope course 1 (Y=6)
    safeSet(1, 6, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(7, 6, z, `${roofStairs}[facing=west,half=bottom]`);

    // Slope course 2 (Y=7)
    safeSet(2, 7, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(6, 7, z, `${roofStairs}[facing=west,half=bottom]`);

    // Ridge slope (Y=8)
    safeSet(3, 8, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(5, 8, z, `${roofStairs}[facing=west,half=bottom]`);
    safeSet(4, 8, z, `${roofSlab}[type=top]`);
  }

  // Gable end walls (fill under roof at Z=6 and Z=14)
  for (const gz of [6, 14]) {
    safeSet(2, 5, gz, woodPlanks);
    safeSet(3, 5, gz, woodPlanks);
    safeSet(4, 5, gz, woodPlanks);
    safeSet(5, 5, gz, woodPlanks);
    safeSet(6, 5, gz, woodPlanks);

    safeSet(3, 6, gz, woodPlanks);
    safeSet(4, 6, gz, woodPlanks);
    safeSet(5, 6, gz, woodPlanks);

    safeSet(4, 7, gz, woodPlanks);
  }

  // Platform Canopy over front boardwalk (X: 1..7, Z: 2..5)
  const canopyPosts = [[1, 2], [4, 2], [7, 2]];
  for (const [cpx, cpz] of canopyPosts) {
    for (let y = 2; y <= 4; y++) {
      safeSet(cpx, y, cpz, woodFence);
    }
  }
  for (let x = 1; x <= 7; x++) {
    safeSet(x, 4, 2, `${woodLog}[axis=x]`);
    safeSet(x, 5, 3, `${roofStairs}[facing=south,half=bottom]`);
    safeSet(x, 4, 2, `${roofStairs}[facing=south,half=bottom]`);
    safeSet(x, 5, 4, `${roofSlab}[type=top]`);
  }

  // Telegraph Mast & Line on rear depot corner (X=1, Z=14)
  for (let y = 5; y <= 12; y++) {
    safeSet(1, y, 14, `${woodStripped}[axis=y]`);
  }
  // Crossarms with insulators
  safeSet(0, 10, 14, woodFence);
  safeSet(2, 10, 14, woodFence);
  safeSet(0, 11, 14, "minecraft:iron_bars");
  safeSet(2, 11, 14, "minecraft:iron_bars");
  safeSet(0, 12, 14, woodFence);
  safeSet(2, 12, 14, woodFence);
  // Simulated wire chains running North along depot roof
  for (let z = 6; z <= 13; z++) {
    if (z % 2 === 0) {
      safeSet(1, 9, z, "minecraft:chain");
    }
  }

  // ==========================================
  // 4. WATER TOWER ON BRACED STILTS
  // ==========================================
  // Center of tower is at X=11, Z=10

  const stiltPillars = [
    [9, 8], [13, 8],
    [9, 12], [13, 12]
  ];

  // Heavy Stilt Pier Foundations & Posts (Y=0..7)
  for (const [sx, sz] of stiltPillars) {
    groundPillar(sx, sz, 0, stonePlinth);
    safeSet(sx, 1, sz, stoneWall);
    for (let y = 2; y <= 7; y++) {
      safeSet(sx, y, sz, `${woodLog}[axis=y]`);
    }
  }

  // Heavy horizontal tie beams at Y=4 and Y=7
  for (const ty of [4, 7]) {
    for (let x = 9; x <= 13; x++) {
      safeSet(x, ty, 8, `${woodLog}[axis=x]`);
      safeSet(x, ty, 12, `${woodLog}[axis=x]`);
    }
    for (let z = 8; z <= 12; z++) {
      safeSet(9, ty, z, `${woodLog}[axis=z]`);
      safeSet(13, ty, z, `${woodLog}[axis=z]`);
    }
  }

  // Cross-bracing (diagonal X-fences) between tower legs
  for (let y = 2; y <= 6; y++) {
    if (y === 4) continue; // Tie beam level
    // North & South stilt faces
    safeSet(10, y, 8, woodFence);
    safeSet(11, y, 8, woodFence);
    safeSet(12, y, 8, woodFence);

    safeSet(10, y, 12, woodFence);
    safeSet(11, y, 12, woodFence);
    safeSet(12, y, 12, woodFence);

    // East & West stilt faces
    safeSet(9, y, 9, woodFence);
    safeSet(9, y, 10, woodFence);
    safeSet(9, y, 11, woodFence);

    safeSet(13, y, 9, woodFence);
    safeSet(13, y, 10, woodFence);
    safeSet(13, y, 11, woodFence);
  }

  // Central vertical water supply riser / standpipe
  groundPillar(11, 10, 0, stonePlinth);
  for (let y = 1; y <= 7; y++) {
    safeSet(11, y, 10, `${woodStripped}[axis=y]`);
  }

  // Maintenance ladder on West stilt leg
  for (let y = 1; y <= 7; y++) {
    safeSet(8, y, 10, `${woodStairs}[facing=east,half=bottom]`);
    safeSet(9, y, 10, "minecraft:ladder[facing=west]");
  }

  // Tower Deck Platform & Support Brackets (Y=7)
  for (let x = 8; x <= 14; x++) {
    for (let z = 7; z <= 13; z++) {
      const dx = Math.abs(x - 11);
      const dz = Math.abs(z - 10);
      if (dx + dz <= 4) {
        safeSet(x, 7, z, woodPlanks);
      }
    }
  }
  // Under-deck inverted stair brackets
  for (let x = 9; x <= 13; x++) {
    safeSet(x, 6, 7, `${woodStairs}[facing=south,half=top]`);
    safeSet(x, 6, 13, `${woodStairs}[facing=north,half=top]`);
  }
  for (let z = 8; z <= 12; z++) {
    safeSet(8, 6, z, `${woodStairs}[facing=east,half=top]`);
    safeSet(14, 6, z, `${woodStairs}[facing=west,half=top]`);
  }

  // Octagonal Wooden Water Tank Body (Y=8 to Y=12)
  for (let y = 8; y <= 12; y++) {
    // Octagonal ring: Center (11, 10)
    for (let x = 9; x <= 13; x++) {
      for (let z = 8; z <= 12; z++) {
        const isCorner = (x === 9 || x === 13) && (z === 8 || z === 12);
        if (!isCorner) {
          safeSet(x, y, z, woodPlanks);
        }
      }
    }

    // Iron reinforcement tension bands around tank at Y=8 and Y=11
    if (y === 8 || y === 11) {
      safeSet(10, y, 7, `${woodTrapdoor}[facing=south,half=bottom]`);
      safeSet(11, y, 7, `${woodTrapdoor}[facing=south,half=bottom]`);
      safeSet(12, y, 7, `${woodTrapdoor}[facing=south,half=bottom]`);

      safeSet(10, y, 13, `${woodTrapdoor}[facing=north,half=bottom]`);
      safeSet(11, y, 13, `${woodTrapdoor}[facing=north,half=bottom]`);
      safeSet(12, y, 13, `${woodTrapdoor}[facing=north,half=bottom]`);

      safeSet(8, y, 9, `${woodTrapdoor}[facing=east,half=bottom]`);
      safeSet(8, y, 10, `${woodTrapdoor}[facing=east,half=bottom]`);
      safeSet(8, y, 11, `${woodTrapdoor}[facing=east,half=bottom]`);

      safeSet(14, y, 9, `${woodTrapdoor}[facing=west,half=bottom]`);
      safeSet(14, y, 10, `${woodTrapdoor}[facing=west,half=bottom]`);
      safeSet(14, y, 11, `${woodTrapdoor}[facing=west,half=bottom]`);
    }
  }

  // Trackside Refill Water Spout Mechanism (Front/Trackside at Z: 5..7, X=11)
  // Boom timber arm extending out towards track
  safeSet(11, 10, 7, `${woodLog}[axis=z]`);
  safeSet(11, 10, 6, `${woodLog}[axis=z]`);
  safeSet(11, 9, 6, "minecraft:iron_bars");
  safeSet(11, 8, 6, "minecraft:hopper");
  safeSet(11, 7, 5, `${woodStairs}[facing=south,half=bottom]`);
  safeSet(11, 8, 5, "minecraft:chain");
  safeSet(11, 9, 5, "minecraft:chain");
  safeSet(11, 10, 5, `${woodTrapdoor}[facing=south,half=top]`);

  // Water level indicator board on tank side
  for (let y = 8; y <= 12; y++) {
    safeSet(9, y, 7, "minecraft:ladder[facing=north]");
  }

  // Conical / Pyramidal Tank Roof (Y=13 to Y=16)
  // Tier 1 - Overhanging Eaves (Y=13)
  for (let x = 8; x <= 14; x++) {
    safeSet(x, 13, 7, `${roofStairs}[facing=south,half=bottom]`);
    safeSet(x, 13, 13, `${roofStairs}[facing=north,half=bottom]`);
  }
  for (let z = 8; z <= 12; z++) {
    safeSet(8, 13, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(14, 13, z, `${roofStairs}[facing=west,half=bottom]`);
  }
  // Fill inside Tier 1
  for (let x = 9; x <= 13; x++) {
    for (let z = 8; z <= 12; z++) {
      safeSet(x, 13, z, roofSolid);
    }
  }

  // Tier 2 - Middle Slope (Y=14)
  for (let x = 9; x <= 13; x++) {
    safeSet(x, 14, 8, `${roofStairs}[facing=south,half=bottom]`);
    safeSet(x, 14, 12, `${roofStairs}[facing=north,half=bottom]`);
  }
  for (let z = 9; z <= 11; z++) {
    safeSet(9, 14, z, `${roofStairs}[facing=east,half=bottom]`);
    safeSet(13, 14, z, `${roofStairs}[facing=west,half=bottom]`);
  }
  for (let x = 10; x <= 12; x++) {
    for (let z = 9; z <= 11; z++) {
      safeSet(x, 14, z, roofSolid);
    }
  }

  // Tier 3 - Upper Peak (Y=15)
  safeSet(11, 15, 9, `${roofStairs}[facing=south,half=bottom]`);
  safeSet(11, 15, 11, `${roofStairs}[facing=north,half=bottom]`);
  safeSet(10, 15, 10, `${roofStairs}[facing=east,half=bottom]`);
  safeSet(12, 15, 10, `${roofStairs}[facing=west,half=bottom]`);
  safeSet(11, 15, 10, roofSolid);

  // Finial Weather Vane / Spire (Y=16)
  safeSet(11, 16, 10, woodFence);

  // ==========================================
  // 5. FRONTIER DETAILS & LIGHTING
  // ==========================================

  // Hitching post at platform edge (X=2..3, Z=1)
  safeSet(2, 2, 1, woodFence);
  safeSet(3, 2, 1, woodFence);
  safeSet(2, 3, 1, `${woodTrapdoor}[facing=south,half=top]`);
  safeSet(3, 3, 1, `${woodTrapdoor}[facing=south,half=top]`);

  // Platform baggage bench & freight cargo
  safeSet(6, 2, 4, `${woodLog}[axis=y]`);
  safeSet(6, 3, 4, `${woodTrapdoor}[facing=south,half=bottom]`);
  safeSet(5, 2, 5, `${woodStairs}[facing=north,half=bottom]`);
  safeSet(6, 2, 5, `${woodStairs}[facing=north,half=bottom]`);

  // Station master oil lanterns
  safeSet(4, 3, 1, "minecraft:lantern[hanging=false]");
  safeSet(1, 3, 2, "minecraft:lantern[hanging=false]");
  safeSet(7, 3, 2, "minecraft:lantern[hanging=false]");
  safeSet(11, 3, 7, "minecraft:lantern[hanging=false]");

  // 6. Return Landmark Specification
  return {
    name: "Rail Depot & Frontier Water Tower",
    seatY: 0,
    anchors: {
      front: [4, 1, 0],
      door: [4, 1, 6],
      track: [14, 1, 0]
    },
    interiors: [
      {
        min: [2, 1, 7],
        max: [6, 4, 13],
        kind: "office"
      }
    ]
  };
}
